import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Force hipcc for ROCm
os.environ.setdefault("CXX", "hipcc")

# Flash-style causal attention (fp32) specialized for head_dim <= 128 (here 96)
# One warp computes one query position i for one (B, H). Online softmax + accumulation.
flash_attn_cpp = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>

static inline __device__ float warp_sum(float v) {
    // full mask for 32 threads
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset);
    }
    return v;
}

__global__ void flash_causal_attn_f32_kernel(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    float* __restrict__ out,
    int B, int H, int T, int D,
    float scale)
{
    // block contains multiple warps
    int warp_in_block = threadIdx.x >> 5;      // /32
    int lane = threadIdx.x & 31;
    int warps_per_block = blockDim.x >> 5;
    int warp_id = (int)blockIdx.x * warps_per_block + warp_in_block;

    int total_warps = B * H * T;
    if (warp_id >= total_warps) return;

    int tmp = warp_id;
    int i = tmp % T; tmp /= T;
    int h = tmp % H; tmp /= H;
    int b = tmp;

    // base pointers
    // layout: [B,H,T,D] contiguous
    const int strideBH = H * T * D;
    const int strideH = T * D;
    const int strideT = D;

    const float* q_ptr = q + b * strideBH + h * strideH + i * strideT;

    // load q elements (up to 3 per lane for D<=96)
    float q0 = 0.f, q1 = 0.f, q2 = 0.f;
    int d0 = lane;
    int d1 = lane + 32;
    int d2 = lane + 64;
    if (d0 < D) q0 = q_ptr[d0];
    if (d1 < D) q1 = q_ptr[d1];
    if (d2 < D) q2 = q_ptr[d2];

    // online softmax state
    float m = -INFINITY;
    float l = 0.f;
    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f;

    // iterate keys 0..i (causal)
    for (int j = 0; j <= i; ++j) {
        const float* k_ptr = k + b * strideBH + h * strideH + j * strideT;

        float partial = 0.f;
        if (d0 < D) partial += q0 * k_ptr[d0];
        if (d1 < D) partial += q1 * k_ptr[d1];
        if (d2 < D) partial += q2 * k_ptr[d2];

        float dot = warp_sum(partial);
        float s = dot * scale;

        // broadcast s from lane0
        s = __shfl(s, 0);

        float m_new = fmaxf(m, s);
        float alpha = expf(m - m_new);
        float beta  = expf(s - m_new);

        // update denom
        l = l * alpha + beta;

        const float* v_ptr = v + b * strideBH + h * strideH + j * strideT;

        // update accum
        if (d0 < D) acc0 = acc0 * alpha + beta * v_ptr[d0];
        if (d1 < D) acc1 = acc1 * alpha + beta * v_ptr[d1];
        if (d2 < D) acc2 = acc2 * alpha + beta * v_ptr[d2];

        m = m_new;
    }

    // normalize
    float inv_l = 1.0f / l;

    float* o_ptr = out + b * strideBH + h * strideH + i * strideT;
    if (d0 < D) o_ptr[d0] = acc0 * inv_l;
    if (d1 < D) o_ptr[d1] = acc1 * inv_l;
    if (d2 < D) o_ptr[d2] = acc2 * inv_l;
}

torch::Tensor flash_causal_attn_f32(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP");
    TORCH_CHECK(k.is_cuda(), "k must be CUDA/HIP");
    TORCH_CHECK(v.is_cuda(), "v must be CUDA/HIP");
    TORCH_CHECK(q.scalar_type() == torch::kFloat32, "q must be fp32");
    TORCH_CHECK(k.scalar_type() == torch::kFloat32, "k must be fp32");
    TORCH_CHECK(v.scalar_type() == torch::kFloat32, "v must be fp32");
    TORCH_CHECK(q.is_contiguous(), "q must be contiguous");
    TORCH_CHECK(k.is_contiguous(), "k must be contiguous");
    TORCH_CHECK(v.is_contiguous(), "v must be contiguous");
    TORCH_CHECK(q.dim() == 4, "q must be [B,H,T,D]");

    int B = (int)q.size(0);
    int H = (int)q.size(1);
    int T = (int)q.size(2);
    int D = (int)q.size(3);
    TORCH_CHECK(D <= 128, "D must be <= 128");

    auto out = torch::empty_like(q);

    float scale = 1.0f / sqrtf((float)D);

    int warps_per_block = 8; // 256 threads
    int threads = warps_per_block * 32;
    int total_warps = B * H * T;
    int blocks = (total_warps + warps_per_block - 1) / warps_per_block;

    hipLaunchKernelGGL(
        flash_causal_attn_f32_kernel,
        dim3(blocks), dim3(threads), 0, 0,
        (const float*)q.data_ptr<float>(),
        (const float*)k.data_ptr<float>(),
        (const float*)v.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        B, H, T, D, scale
    );

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("flash_causal_attn_f32", &flash_causal_attn_f32, "Flash causal attention fp32 (HIP)");
}
'''

flash_attn_ext = load_inline(
    name="flash_causal_attn_ext",
    cpp_sources=flash_attn_cpp,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class NewGELU(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return 0.5 * x * (1.0 + torch.tanh(math.sqrt(2.0 / math.pi) * (x + 0.044715 * torch.pow(x, 3.0))))


class CausalSelfAttentionNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer(
            "bias",
            torch.tril(torch.ones(max_seqlen, max_seqlen)).view(1, 1, max_seqlen, max_seqlen),
        )
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        hs = C // self.n_head

        # [B, nh, T, hs] contiguous for our kernel
        k = k.view(B, T, self.n_head, hs).transpose(1, 2).contiguous()
        q = q.view(B, T, self.n_head, hs).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, hs).transpose(1, 2).contiguous()

        # Custom fused causal attention: y = softmax(qk^T) @ v, no materialized [T,T]
        y = flash_attn_ext.flash_causal_attn_f32(q, k, v)

        # back to [B, T, C]
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y


class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttentionNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(
            dict(
                c_fc=nn.Linear(n_embd, 4 * n_embd),
                c_proj=nn.Linear(4 * n_embd, n_embd),
                act=NewGELU(),
                dropout=nn.Dropout(resid_pdrop),
            )
        )
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x


