__global__ void flash_causal_attn_f32_kernel(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    float* __restrict__ out,
    int B, int H, int T, int D,
    float scale)
{
    int lane = threadIdx.x & (warpSize - 1);
    int wave_in_block = threadIdx.x / warpSize;
    int waves_per_block = blockDim.x / warpSize;
    int wave_id = (int)blockIdx.x * waves_per_block + wave_in_block;

    int total_waves = B * H * T;
    if (wave_id >= total_waves) return;

    int tmp = wave_id;
    int i = tmp % T; tmp /= T;
    int h = tmp % H; tmp /= H;
    int b = tmp;

    const int strideBH = H * T * D;
    const int strideH = T * D;
    const int strideT = D;

    const float* q_ptr = q + b * strideBH + h * strideH + i * strideT;

    // each lane handles d = lane, lane+warpSize
    float q0 = 0.f, q1 = 0.f;
    int d0 = lane;
    int d1 = lane + warpSize;
    if (d0 < D) q0 = q_ptr[d0];
    if (d1 < D) q1 = q_ptr[d1];

    float m = -INFINITY;
    float l = 0.f;
    float acc0 = 0.f, acc1 = 0.f;

    for (int j = 0; j <= i; ++j) {
        const float* k_ptr = k + b * strideBH + h * strideH + j * strideT;
        float partial = 0.f;
        if (d0 < D) partial += q0 * k_ptr[d0];
